result.text:
  color: var(--ink-3);
}
.empty .e-icon svg { width: 26px; height: 26px; }
.empty h3 { font-size: 16px; font-weight: 650; letter-spacing: -.01em; }
.empty p { font-size: 13.5px; color: var(--ink-3); margin: 5px auto 0; max-width: 430px; }
.empty .e-actions { display: flex; gap: 9px; justify-content: center; margin-top: 18px; flex-wrap: wrap; }

.howto { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.howto .step {
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  padding: 14px;
  background: var(--surface-2);
}
.howto .step .n {
  width: 22px; height: 22px;
  border-radius: 50%;
  display: grid; place-items: center;
  background: var(--brand);
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 8px;
}
.howto .step h4 { font-size: 13.5px; font-weight: 650; margin-bottom: 2px; }
.howto .step p { font-size: 12.5px; color: var(--ink-3); line-height: 1.45; }

.two-col {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.mini-list { display: flex; flex-direction: column; }
.mini-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 18px;
  border-bottom: 1px solid var(--line);
  font-size: 13.5px;
}
.mini-row:last-child { border-bottom: none; }
.mini-row .m-main { min-width: 0; }
.mini-row .m-main .t { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.mini-row .m-main .s { font-size: 12px; color: var(--ink-3); }
.mini-row .num { margin-left: auto; font-variant-numeric: tabular-nums; font-weight: 640; white-space: nowrap; }

.hint-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px;
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  border: 1px solid var(--line);
  font-size: 13px;
  color: var(--ink-2);
}
.hint-bar svg { width: 17px; height: 17px; flex: 0 0 auto; color: var(--brand); }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* ---------- Animaciones ------------------------------------------------- */

@keyframes spin { to { transform: rotate(360deg); } }
